from flask import Flask, redirect, url_for

app = Flask(__name__)

@app.route('/new')
def new_page():
    return 'Welcome to the new page!'

@app.route('/old')
def old_page():
    return redirect(url_for('new_page'))

if __name__ == '__main__':
    app.run(debug=True)
